import React from "react";
import "./HomePage.css";

const HomePage = () => {
  return (
    <div className="homepage-container">
      {/* Top Corner Buttons */}
      <div className="top-corner-buttons">
        <button className="corner-btn review-btn"></button>
        <button className="corner-btn scoreboard-btn"></button>
      </div>

      {/* Game Title */}
      <div className="game-title-section">
        <h1 className="game-title"></h1>
      </div>

      {/* Difficulty Levels - Center */}
      <div className="difficulty-section">
        <button className="level-btn easy-btn"></button>
        <button className="level-btn medium-btn"></button>
        <button className="level-btn hard-btn"></button>
      </div>

      {/* Game Type Buttons - Bottom */}
      <div className="game-type-section">
        <button className="game-type-btn jumble-btn"></button>
        <button className="game-type-btn crossword-btn"></button>
        <button className="game-type-btn mcq-btn"></button>
      </div>
    </div>
  );
};

export default HomePage;
